/**
 * The protections for a report's market (and, in India, its state).
 * @returns {{ market, label, verified, items[] } | null}
 */
function protectionsFor(market, location = '') {
  const m = MARKETS[market];
  if (!m) return null;
  let items = [...m.items], label = m.label;
  if (m.byState) {
    const st = Object.values(m.byState).find(s => s.match.test(String(location || '')));
    if (st) { items = [...items, ...st.items]; label = `${m.label} \u2014 ${st.label}`; }
  }
  return { market, label, verified: VERIFIED, disclaimer: 'General information about buyers\u2019 rights, not legal advice for your case. Laws change: check the current position with a lawyer before you act.', items };
}

module.exports = { protectionsFor, VERIFIED, _MARKETS: MARKETS };
